def apply(S):
    for L, p in P.items():
        s = S[L]
        old = p["old_scr"]
        s["fine"] = [x.replace(f"<b>{old}</b>", f"<b>{p['scr']}</b>").replace(old, p["scr"]) for x in s["fine"]] + p["fine_add"]
        s["ft3"] = s["ft3"].replace(old, p["scr"])
        for k in ("prem", "biz", "py_b", "biz_w", "rb", "pl", "bh", "b5", "b10", "each", "tot", "bn", "nt", "n1t", "n1p", "n1l", "n2t", "n2l"):
            s[k] = p[k]
